create extension if not exists vector;
create table if not exists workspaces(id uuid primary key default gen_random_uuid(),name text not null,created_at timestamptz not null default now());
create table if not exists brands(id uuid primary key default gen_random_uuid(),workspace_id uuid not null references workspaces(id) on delete cascade,name text not null,voice text,description text,audience text,created_at timestamptz not null default now());
create table if not exists content_drafts(id uuid primary key default gen_random_uuid(),workspace_id uuid not null references workspaces(id) on delete cascade,title text,platform text,caption text not null,status text not null default 'draft',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists approvals(id uuid primary key default gen_random_uuid(),workspace_id uuid not null references workspaces(id) on delete cascade,content_draft_id uuid not null references content_drafts(id) on delete cascade,status text not null default 'pending',reviewer_id uuid,created_at timestamptz not null default now());
create table if not exists agent_tasks(id uuid primary key default gen_random_uuid(),workspace_id uuid not null references workspaces(id) on delete cascade,kind text not null,status text not null default 'created',input jsonb not null default '{}'::jsonb,output jsonb,checkpoint jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists audit_events(id uuid primary key default gen_random_uuid(),workspace_id uuid not null references workspaces(id) on delete cascade,actor_type text not null,action text not null,resource_type text,resource_id uuid,metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create index if not exists idx_brands_workspace on brands(workspace_id);create index if not exists idx_drafts_workspace_status on content_drafts(workspace_id,status);create index if not exists idx_tasks_workspace_status on agent_tasks(workspace_id,status);create index if not exists idx_audit_workspace_time on audit_events(workspace_id,created_at desc);